#!/usr/bin/env python3
"""Generate reagent kit policy financial analysis report."""

import csv
import json
from pathlib import Path

ROOT = Path("/root")


def parse_bool(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() in {"true", "1", "yes", "y"}


def parse_float(value):
    if value is None:
        return 0.0
    return float(str(value).strip().replace(",", ""))


def parse_int(value):
    if value is None:
        return 0
    return int(float(str(value).strip().replace(",", "")))


def read_csv(path):
    with path.open(newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def round2(value):
    return round(float(value) + 0.0, 2)


def main():
    with (ROOT / "assay_manifest.json").open(encoding="utf-8") as f:
        manifest = json.load(f)
    carrier_rows = read_csv(ROOT / "carrier_cost.csv")
    billing_rows = read_csv(ROOT / "billing.csv")
    override_rows = read_csv(ROOT / "lab_overrides.csv")
    with (ROOT / "report_template.json").open(encoding="utf-8") as f:
        template = json.load(f)

    carrier_cost_by_type = {
        row["carrier_type"].strip(): parse_float(row["carrier_cost_usd"])
        for row in carrier_rows
    }

    approved_overrides = {}
    for row in override_rows:
        if row.get("status") != "approved":
            continue
        assay_id = row.get("assay_id", "").strip()
        revision = parse_int(row.get("revision"))
        if assay_id not in approved_overrides or revision > approved_overrides[assay_id][0]:
            active_labs_col = "active_labs"
            if active_labs_col not in row:
                candidates = [key for key in row if "active" in key.lower() and "lab" in key.lower()]
                if not candidates:
                    raise KeyError("Could not find active labs column in lab_overrides.csv")
                active_labs_col = candidates[0]
            approved_overrides[assay_id] = (revision, parse_int(row[active_labs_col]))

    assays = []
    for region in manifest.get("regions", []):
        for assay in region.get("assays", []):
            if parse_bool(assay.get("in_scope")):
                assays.append(assay)

    analysis_assays = []
    for assay in sorted(assays, key=lambda item: item["assay_id"]):
        assay_id = assay["assay_id"]
        labels = {assay.get("assay_name", "")}
        labels.update(assay.get("aliases") or [])
        labels = {label.strip() for label in labels if str(label).strip()}

        matching_billing = [
            row for row in billing_rows
            if row.get("assay_label", "").strip() in labels and parse_bool(row.get("is_active"))
        ]
        if not matching_billing:
            raise ValueError(f"No active billing row found for assay {assay_id}")
        billing = max(matching_billing, key=lambda row: row.get("effective_month", ""))
        payment = parse_float(billing["payment_per_run_per_lab_usd"])

        if assay_id in approved_overrides:
            active_labs = approved_overrides[assay_id][1]
        else:
            active_labs = parse_int(assay.get("default_active_labs"))

        carrier_type = assay["carrier_type"]
        if carrier_type not in carrier_cost_by_type:
            raise ValueError(f"No carrier cost found for type {carrier_type!r}")
        carrier_cost = carrier_cost_by_type[carrier_type]

        reagent_price = parse_float(assay["reagent_price_per_1000_tests_usd"])
        tests_small = parse_float(assay["tests_per_lab_per_run_small"])
        tests_bulk = parse_float(assay["tests_per_lab_per_run_bulk"])

        annual_revenue_small = payment * active_labs * 24
        annual_revenue_bulk = payment * active_labs * 12
        annual_reagent_cost_small = reagent_price * active_labs * tests_small * 24 / 1000
        annual_reagent_cost_bulk = reagent_price * active_labs * tests_bulk * 12 / 1000
        annual_carrier_cost_small = carrier_cost * active_labs * 24
        annual_carrier_cost_bulk = carrier_cost * active_labs * 12
        annual_margin_small = annual_revenue_small - annual_reagent_cost_small - annual_carrier_cost_small
        annual_margin_bulk = annual_revenue_bulk - annual_reagent_cost_bulk - annual_carrier_cost_bulk
        difference = annual_margin_bulk - annual_margin_small

        analysis_assays.append({
            "assay_id": assay_id,
            "assay_name": assay["assay_name"],
            "active_labs": active_labs,
            "payment_per_run_per_lab_usd": round2(payment),
            "annual_revenue_small_kit_usd": round2(annual_revenue_small),
            "annual_revenue_bulk_kit_usd": round2(annual_revenue_bulk),
            "annual_reagent_cost_small_kit_usd": round2(annual_reagent_cost_small),
            "annual_reagent_cost_bulk_kit_usd": round2(annual_reagent_cost_bulk),
            "annual_carrier_cost_small_kit_usd": round2(annual_carrier_cost_small),
            "annual_carrier_cost_bulk_kit_usd": round2(annual_carrier_cost_bulk),
            "annual_margin_small_kit_usd": round2(annual_margin_small),
            "annual_margin_bulk_kit_usd": round2(annual_margin_bulk),
            "annual_margin_difference_bulk_minus_small_usd": round2(difference),
        })

    total_small = round2(sum(item["annual_margin_small_kit_usd"] for item in analysis_assays))
    total_bulk = round2(sum(item["annual_margin_bulk_kit_usd"] for item in analysis_assays))
    total_difference = round2(sum(item["annual_margin_difference_bulk_minus_small_usd"] for item in analysis_assays))
    absolute_difference = round2(abs(total_difference))

    decision = "adopt_bulk_kit" if abs(total_difference) < 7000 else "keep_small_kit"
    if decision == "adopt_bulk_kit":
        justification = (
            f"Adopt the bulk kit because the absolute total annual margin difference "
            f"is ${absolute_difference:.2f}, below the $7000 threshold."
        )
    else:
        justification = (
            f"Keep the small kit because the absolute total annual margin difference "
            f"is ${absolute_difference:.2f}, meeting or exceeding the $7000 threshold."
        )

    report = {
        "metadata": template["metadata"],
        "analysis": {
            "assumptions": {
                "in_scope_filter": "Only manifest assays with in_scope equal to true are included.",
                "billing_resolution": "Active billing rows are matched by assay_name or alias, retaining the latest effective_month.",
                "lab_override_resolution": "Approved lab override rows are matched by assay_id, retaining the highest revision; otherwise default_active_labs is used.",
                "carrier_cost_formula": "carrier_cost_usd * active_labs * runs_per_year",
                "small_kit_runs_per_year": 24,
                "bulk_kit_runs_per_year": 12,
            },
            "assays": analysis_assays,
            "totals": {
                "total_annual_margin_small_kit_usd": total_small,
                "total_annual_margin_bulk_kit_usd": total_bulk,
                "total_annual_margin_difference_bulk_minus_small_usd": total_difference,
                "absolute_total_margin_difference_usd": absolute_difference,
            },
            "recommendation": {
                "decision": decision,
                "justification": justification,
            },
        },
    }

    with (ROOT / "reagent_policy_report.json").open("w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)
        f.write("\n")

    summary_lines = [
        "# Reagent Policy Summary",
        f"Total small-kit margin (USD): {total_small:.2f}",
        f"Total bulk-kit margin (USD): {total_bulk:.2f}",
        f"Absolute difference (USD): {absolute_difference:.2f}",
        f"Final decision: {decision}",
        justification,
    ]
    with (ROOT / "reagent_policy_summary.md").open("w", encoding="utf-8") as f:
        f.write("\n".join(summary_lines) + "\n")


if __name__ == "__main__":
    main()

